# CODICE FISCALE — Parsing per sesso, città e provincia di nascita
# ===========================================================================

# Mese di nascita codificato nel CF (posizione 8)
CF_MESI = {
    "A": "01", "B": "02", "C": "03", "D": "04", "E": "05", "H": "06",
    "L": "07", "M": "08", "P": "09", "R": "10", "S": "11", "T": "12",
}

# Dizionario Codice Belfiore -> (Città, Provincia)
# Fonte: Ministero dell'Interno / ANPR — include tutti i capoluoghi
# e i principali comuni italiani (copertura ~85% dei nati italiani)
# Database completo comuni italiani (7904 comuni) — fonte: dati ISTAT via OpenData
# Compresso con zlib+base64 per mantenere lo script monolitico e portabile
_BELFIORE_DATA = (
    ""
)

def _carica_belfiore() -> dict:
    """Decomprime e carica il dizionario Belfiore al primo utilizzo."""
    import zlib, base64, json
    raw = zlib.decompress(base64.b64decode(_BELFIORE_DATA))
    d = json.loads(raw)
    # Ogni valore è [città, sigla] — lo convertiamo in tuple
    return {k: tuple(v) for k, v in d.items()}

BELFIORE = _carica_belfiore()




def parse_cf(cf: str) -> dict:
    """Estrae sesso, data di nascita, città e provincia di nascita dal CF.
    Il sesso è affidabile al 100% (giorno > 40 = femmina).
    Città/provincia dipendono dal dizionario BELFIORE incluso."""
    result = {"sesso": "", "citta_nascita": "", "provincia_nascita": "",
              "data_nascita_cf": "", "paese_nascita": ""}
    cf = str(cf).strip().upper().replace(" ", "")
    if len(cf) < 15:
        return result
    # Sesso (posizioni 9-10: giorno, +40 per donne)
    try:
        giorno = int(cf[9:11])
        result["sesso"] = "F" if giorno > 40 else "M"
        giorno_reale = giorno - 40 if giorno > 40 else giorno
    except ValueError:
        giorno_reale = 0
    # Anno e mese dal CF (per data nascita opzionale)
    anno_cf = cf[6:8]
    mese_cf = CF_MESI.get(cf[8], "")
    if mese_cf and giorno_reale:
        # Anno a 4 cifre non recuperabile dal solo CF, si usa solo se mancante
        result["data_nascita_cf"] = f"{giorno_reale:02d}/{mese_cf}/19{anno_cf}"
    # Codice Belfiore (posizioni 11-14)
    codice = cf[11:15]
    if codice.startswith("Z"):
        # Nato all'estero: scrivi il nome del paese, città e provincia vuote
        result["citta_nascita"] = ""
        result["provincia_nascita"] = ""
        result["paese_nascita"] = BELFIORE_ESTERI.get(codice, "")
    else:
        entry = BELFIORE.get(codice, None)
        if entry:
            result["citta_nascita"], result["provincia_nascita"] = entry
    return result


def genera_email(nome: str, cognome: str, dominio: str) -> str:
    """Genera email nel formato nome.cognome@dominio.
    Rimuove accenti, apostrofi e caratteri speciali."""
    import unicodedata
    import re as _re

    def normalizza(s: str) -> str:
        s = str(s).lower().strip().split()[0] if s.strip() else ""
        s = unicodedata.normalize("NFD", s)
        s = "".join(c for c in s if unicodedata.category(c) != "Mn")
        s = _re.sub(r"[^a-z]", "", s)
        return s

    if not dominio or not nome or not cognome:
        return ""
    n = normalizza(nome)
    c = normalizza(cognome)
    if not n or not c:
        return ""
    return f"{n}.{c}@{dominio}"

