def normalize_header(h: str) -> str:
    """Normalizza intestazione rimuovendo accenti, punteggiatura e testo extra."""
    import unicodedata
    s = str(h).lower().strip()
    # Rimuove testo tra parentesi
    import re
    s = re.sub(r"[(\[{].*?[)\]}]", "", s)
    # Rimuove punteggiatura ridondante
    s = re.sub(r"[*_/\\]", " ", s)
    # Normalizza accenti (es. "città" -> "citta")
    s = unicodedata.normalize("NFD", s)
    s = "".join(c for c in s if unicodedata.category(c) != "Mn")
    # Compatta spazi
    s = re.sub(r"\s+", " ", s).strip()
    return s


