def find_header_row(wb_path: str) -> int:
    """Scansiona le prime 15 righe e trova quella con piu' corrispondenze
    ai nomi di colonna attesi. Restituisce l'indice (0-based) da usare come header."""
    from openpyxl import load_workbook
    wb = load_workbook(wb_path, read_only=True, data_only=True)
    ws = wb.active
    best_row = 0
    best_score = 0
    for row_idx, row in enumerate(ws.iter_rows(max_row=15, values_only=True)):
        score = 0
        for cell in row:
            if cell is None:
                continue
            norm = normalize_header(str(cell))
            for patterns in COLUMN_PATTERNS.values():
                if any(p in norm or norm in p for p in patterns):
                    score += 1
                    break
        if score > best_score:
            best_score = score
            best_row = row_idx
    wb.close()
    return best_row


def detect_columns(df: pd.DataFrame) -> dict:
    """Rileva le colonne con word-boundary matching e deduplicazione.
    Ogni colonna viene assegnata a un solo campo (il piu' specifico)."""
    import re as _re
    mapping = {}
    used_cols = set()

    # Ordina campi per specificita' decrescente:
    # chi ha il pattern piu' lungo vince in caso di ambiguita'
    field_order = sorted(
        COLUMN_PATTERNS.keys(),
        key=lambda k: max(len(p) for p in COLUMN_PATTERNS[k]),
        reverse=True
    )

    for field_key in field_order:
        patterns = COLUMN_PATTERNS[field_key]
        best_col   = None
        best_score = 0

        for col in df.columns:
            if col in used_cols:
                continue
            norm = normalize_header(str(col))
            for p in patterns:
                # Word-boundary matching: "nome" NON matcha "cognome"
                pat = r"(?<![a-z])" + _re.escape(p) + r"(?![a-z])"
                if _re.search(pat, norm):
                    score = len(p)
                    if score > best_score:
                        best_score = score
                        best_col   = col

        if best_col is not None:
            mapping[field_key] = best_col
            used_cols.add(best_col)

    return mapping


def clean(val) -> str:
    if val is None:
        return ""
    try:
        if pd.isna(val):
            return ""
    except (TypeError, ValueError):
        pass
    return str(val).strip()


def parse_date(val) -> str:
    """Converte valori data in stringa GG/MM/AAAA."""
    if val is None:
        return ""
    try:
        if pd.isna(val):
            return ""
    except (TypeError, ValueError):
        pass
    if isinstance(val, (pd.Timestamp, datetime, date)):
        try:
            return pd.Timestamp(val).strftime("%d/%m/%Y")
        except Exception:
            return ""
    if isinstance(val, (int, float)):
        if val < 1000:
            return str(int(val))
        try:
            d = datetime(1899, 12, 30) + pd.Timedelta(days=int(val))
            return d.strftime("%d/%m/%Y")
        except Exception:
            return str(val)
    s = str(val).strip()
    for fmt in ("%Y-%m-%d %H:%M:%S", "%Y-%m-%d", "%d/%m/%Y", "%d.%m.%Y", "%d-%m-%Y"):
        try:
            return datetime.strptime(s, fmt).strftime("%d/%m/%Y")
        except ValueError:
            continue
    return s


def anno_to_date(val) -> str:
    """Converte un anno (es. 2014) in 01/01/AAAA per il campo Data Assunzione."""
    s = clean(val)
    if not s:
        return ""
    # Se e' gia' una data completa GG/MM/AAAA
    if "/" in s and len(s) >= 8:
        return s
    # Se e' solo un anno a 4 cifre
    if s.isdigit() and len(s) == 4:
        return f"01/01/{s}"
    return s


