def to_nome_paese(val: str) -> str:
    """Converte codice nazione (2 o 3 lettere) in nome italiano completo."""
    s = clean(val).upper()
    if not s:
        return ""
    return NAZIONE_NOMI.get(s, s)  # fallback: prime 2 lettere


