# id Tipologia Contrattuale -> numero (dalla nota nel template)
# 1=apprendistato, 2=cassa integrati, 3=a progetto,
# 4=tempo determinato, 5=tempo indeterminato, 6=inserimento,
# 7=tempo parziale, 8=intermittente, 9=tirocinio,
# 10=altro, 11=somministrazione, 12=collaborazione
# ---------------------------------------------------------------------------
_CONTRATTO_RULES = [
    (["indeterminat"],                        5),
    (["determinat"],                          4),
    (["apprendistato", "apprendist"],         1),
    (["collaborazion"],                       12),
    (["progetto"],                            3),
    (["parziale", "part time", "part-time"],  7),
    (["intermittent"],                        8),
    (["somministrazion"],                     11),
    (["tirocinio", "stage", "tirocin"],       9),
    (["inseriment"],                          6),
    (["cassa integrat"],                      2),
]


def map_tipo_contratto(val: str) -> str:
    """Restituisce il numero ID del tipo contratto (come stringa)."""
    s = clean(val).lower()
    if not s:
        return ""
    for keywords, id_num in _CONTRATTO_RULES:
        for kw in keywords:
            if kw in s:
                return str(id_num)
    return "10"  # _Altro (specificare nelle note)


