# Main
# ---------------------------------------------------------------------------

def scegli_file_interattivo() -> str:
    """Se non viene passato nessun argomento, cerca xlsx nella cartella
    e fa scegliere all'utente quale usare."""
    cartella = os.path.dirname(os.path.abspath(__file__))
    file_xlsx = [
        f for f in os.listdir(cartella)
        if f.lower().endswith(".xlsx")
        and f not in ("modello-importazione-corsisti.xlsx", "template-import-test.xlsx")
    ]

    if not file_xlsx:
        print("Nessun file .xlsx trovato nella cartella dello script.")
        print(f"Cartella cercata: {cartella}")
        sys.exit(1)

    if len(file_xlsx) == 1:
        scelta = file_xlsx[0]
        print(f"File trovato automaticamente: {scelta}")
        return os.path.join(cartella, scelta)

    print("\nFile .xlsx disponibili nella cartella:")
    for i, nome in enumerate(file_xlsx, start=1):
        print(f"  {i}) {nome}")
    print()

    while True:
        try:
            n = int(input(f"Scegli il numero del file sorgente (1-{len(file_xlsx)}): "))
            if 1 <= n <= len(file_xlsx):
                return os.path.join(cartella, file_xlsx[n - 1])
        except (ValueError, KeyboardInterrupt):
            pass
        print("Inserisci un numero valido.")


def main():
    parser = argparse.ArgumentParser(
        description="Genera i file di importazione corsisti dal file sorgente."
    )
    parser.add_argument("sorgente",           nargs="?", default=None,
                        help="File Excel sorgente (.xlsx) — opzionale")
    parser.add_argument("--id-corso",         default="", help="ID corso")
    parser.add_argument("--piva-azienda",     default="", help="P.IVA azienda")
    parser.add_argument("--id-sede",          default="", help="ID sede")
    parser.add_argument("--id-intermediario", default="", help="ID intermediario")
    parser.add_argument("--settore-ateco",    default="", help="Codice ATECO")
    parser.add_argument("--email-domain",     default="",
                        help="Dominio per generare le email (es. azienda.it)"
                             " -> genera nome.cognome@dominio")
    parser.add_argument("--output-dir",       default="", help="Cartella di output")
    args = parser.parse_args()

    # Se non e' stato passato il file, lo cerca/chiede interattivamente
    if args.sorgente is None:
        file_sorgente = scegli_file_interattivo()
    else:
        file_sorgente = args.sorgente

    if not os.path.isfile(file_sorgente):
        print(f"Errore: file '{file_sorgente}' non trovato.")
        sys.exit(1)

    extras = {
        "id_corso":         args.id_corso,
        "piva_azienda":     args.piva_azienda,
        "id_sede":          args.id_sede,
        "id_intermediario": args.id_intermediario,
        "settore_ateco":    args.settore_ateco,
        "email_domain":     args.email_domain,
    }

    output_dir = args.output_dir or os.path.dirname(os.path.abspath(file_sorgente))
    os.makedirs(output_dir, exist_ok=True)

    print(f"Lettura file: {file_sorgente}")

    # Rileva automaticamente la riga di intestazione
    header_row = find_header_row(file_sorgente)
    if header_row > 0:
        print(f"Intestazione rilevata alla riga {header_row + 1} (saltate {header_row} righe)")
    df = pd.read_excel(file_sorgente, header=header_row, dtype=str)
    df = df.dropna(how="all")
    # Rimuove colonne senza nome
    df = df.loc[:, df.columns.notna()]
    df = df.loc[:, ~df.columns.str.startswith("Unnamed")]

    cols = detect_columns(df)
    print(f"Colonne rilevate: {len(cols)}/19")

    # Mostra anteprima del mapping trovato
    print("\nMapping colonne:")
    for k, v in sorted(cols.items()):
        print(f"  {k:20s} <- '{v}'")

    mancanti = [k for k in COLUMN_PATTERNS.keys() if k not in cols]
    if mancanti:
        print(f"\nAttenzione: colonne non trovate -> {mancanti}")
    print()

    rows1, rows2 = [], []
    unmapped_titoli    = set()
    unmapped_contratti = set()

    for _, row in df.iterrows():
        r1 = build_output1_row(row, cols, extras)
        rows1.append(r1)
        rows2.append(build_output2_row(row, cols))

        titolo_orig    = clean(row.get(cols.get("titolo_studio", ""), ""))
        contratto_orig = clean(row.get(cols.get("tipo_contratto", ""), ""))

        if titolo_orig and map_titolo_studio(titolo_orig) == "":
            unmapped_titoli.add(titolo_orig)
        if contratto_orig and map_tipo_contratto(contratto_orig) == "10":
            unmapped_contratti.add(contratto_orig)

    out1 = os.path.join(output_dir, "modello-importazione-corsisti.xlsx")
    out2 = os.path.join(output_dir, "template-import-test.xlsx")

    write_excel(rows1, OUTPUT1_HEADERS, out1)
    print(f"Output 1 salvato: {out1}  ({len(rows1)} righe)")

    write_excel(rows2, OUTPUT2_HEADERS, out2)
    print(f"Output 2 salvato: {out2}  ({len(rows2)} righe)")

    # Riepilogo aziende
    if "azienda" in cols:
        aziende = df[cols["azienda"]].str.strip().value_counts()
        print("\nRiepilogo per azienda:")
        for az, cnt in aziende.items():
            print(f"  {az}: {cnt} dipendenti")

    # Avvisi
    if unmapped_titoli:
        print("\nATTENZIONE - Titoli di studio non riconosciuti (lasciati vuoti):")
        for t in sorted(unmapped_titoli):
            print(f"  '{t}'")
    if unmapped_contratti:
        print("\nATTENZIONE - Contratti non riconosciuti (impostati come '10 - Altro'):")
        for c in sorted(unmapped_contratti):
            print(f"  '{c}'")


if __name__ == "__main__":
    main()
